mapper.select:
SELECT COUNT(1) FROM behavior_mgmt
WHERE deleted=0

    AND status = #{status}


    AND leave_type = #{leaveType}


    AND attendance_sync = #{attendanceSync}


    AND create_time >= #{startDateTime} and create_time  <=  #{endDateTime}

SELECT leave_type AS name, COUNT(1) AS count FROM behavior_mgmt WHERE deleted=0
AND create_time >= #{startDateTime} and create_time <= #{endDateTime}
GROUP BY leave_type

SELECT leave_type AS name, COUNT(1) AS count
FROM `behavior_mgmt` AS b LEFT JOIN student_info AS s ON b.student_id = s.id
WHERE b.deleted=0

    AND b.create_time >= #{startDateTime} and b.create_time  <=  #{endDateTime}


    AND s.class_name = #{className}

GROUP BY b.leave_type

SELECT DATE_FORMAT(create_time, '%Y-%m-%d') AS name, COUNT(1) AS count FROM behavior_mgmt WHERE deleted=0
AND create_time >= #{startDateTime} and create_time <= #{endDateTime}
GROUP BY name ORDER BY name

SELECT DATE_FORMAT(b.create_time, '%Y-%m-%d') AS name, COUNT(1) AS count FROM `behavior_mgmt` AS b LEFT JOIN student_info AS s ON b.student_id = s.id WHERE b.deleted=0
AND b.create_time >= #{startDateTime} and b.create_time <= #{endDateTime}
AND s.class_name = #{className}
GROUP BY name, b.create_time ORDER BY name

SELECT COUNT(1) FROM behavior_mgmt AS b LEFT JOIN student_info AS s ON b.student_id = s.id
WHERE b.deleted=0

    AND b.status = #{status}


    AND b.leave_type = #{leaveType}


    AND b.attendance_sync = #{attendanceSync}


    AND s.class_name = #{className}


    AND b.create_time >= #{startDateTime} and b.create_time  <=  #{endDateTime}

SELECT COUNT(1) FROM behavior_mgmt AS b LEFT JOIN student_info AS s ON b.student_id = s.id
WHERE b.deleted=0


    AND grade = #{grade}


    AND class_name = #{className}


    AND b.create_time >= #{startTime} and b.create_time  <=  #{endTime}
